  v_expected:=v_role='sky_guide_sync_writer' and v_func=any(array['iso_instant(text)','valid_partial_time(boolean,text,text,text,text)','valid_time_range(boolean,text,text,boolean,text,text)','graph_edges(bigint)','apply_sync_metadata_cas(text,bigint,text,bigint,text,text)','lock_sync_commit_control()','activate_sync_commit_intent(uuid)','require_sync_commit_intent(uuid,text)','apply_sync_commit_cas(uuid,text)','settle_sync_commit_intent(uuid,text)']);
