if exists(select 1 from pg_namespace n join pg_roles r on r.oid=n.nspowner where n.nspname='sky_private' and r.rolname in('sky_guide_sync_reader','sky_guide_sync_writer'))
or exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_roles r on r.oid=c.relowner where n.nspname='sky_private' and r.rolname in('sky_guide_sync_reader','sky_guide_sync_writer'))
or exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_roles r on r.oid=p.proowner where n.nspname='sky_private' and r.rolname in('sky_guide_sync_reader','sky_guide_sync_writer')) then raise exception 'Runtime role became owner';end if;
if exists(select 1 from pg_namespace n cross join lateral unnest(coalesce(n.nspacl,acldefault('n',n.nspowner))) acl cross join lateral aclexplode(array[acl]) a left join pg_roles r on r.oid=a.grantee where n.nspname='sky_private' and a.grantee<>n.nspowner and (r.rolname is null or r.rolname not in('sky_guide_sync_reader','sky_guide_sync_writer') or a.is_grantable))
