do $validation_catalog$ declare role_name text;table_name text;column_name text;priv text;fn text;begin
 if (select jsonb_agg(jsonb_build_object('name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'definer',p.prosecdef,'bodyMd5',md5(p.prosrc),'owner',r.rolname) order by p.proname collate pg_catalog."C") from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_roles r on r.oid=p.proowner where n.nspname='sky_private' and p.proname in('enter_release_validation_statement','leave_release_validation_statement','validate_release_epoch')) is distinct from '[{"name":"enter_release_validation_statement","args":"","result":"trigger","definer":true,"bodyMd5":"f92de9bd429a275a5a30375b039f9646","owner":"postgres"},{"name":"leave_release_validation_statement","args":"","result":"trigger","definer":true,"bodyMd5":"96eb095de72565cb95f3350bfa863a91","owner":"postgres"},{"name":"validate_release_epoch","args":"p_catalog_version text","result":"void","definer":true,"bodyMd5":"6dd871de7f44b50b31fc5f62718abff2","owner":"postgres"}]'::jsonb then raise exception 'Validation definer allowlist changed';end if;
 if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_roles r on r.oid=p.proowner where n.nspname='sky_private' and p.proname='validate_release_metadata' and r.rolname<>'postgres') then raise exception 'Wrapper owner changed';end if;
 if (select jsonb_agg(jsonb_build_object('table',c.relname,'position',a.attnum,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'generated',a.attgenerated,'defaultExpression',pg_get_expr(d.adbin,d.adrelid)) order by c.relname collate pg_catalog."C",a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where n.nspname='sky_private' and c.relname in('release_validation_clock','release_validation_witness') and a.attnum>0 and not a.attisdropped) is distinct from '[{"table":"release_validation_clock","position":1,"name":"singleton","type":"integer","notNull":true,"generated":"","defaultExpression":null},{"table":"release_validation_clock","position":2,"name":"epoch","type":"bigint","notNull":true,"generated":"","defaultExpression":null},{"table":"release_validation_clock","position":3,"name":"write_depth","type":"integer","notNull":true,"generated":"","defaultExpression":null},{"table":"release_validation_clock","position":4,"name":"writer_xid","type":"xid8","notNull":false,"generated":"","defaultExpression":null},{"table":"release_validation_witness","position":1,"name":"catalog_version","type":"text","notNull":true,"generated":"","defaultExpression":null},{"table":"release_validation_witness","position":2,"name":"transaction_id","type":"xid8","notNull":true,"generated":"","defaultExpression":null},{"table":"release_validation_witness","position":3,"name":"epoch","type":"bigint","notNull":true,"generated":"","defaultExpression":null}]'::jsonb then raise exception 'Internal validation columns changed';end if;
 if (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_roles r on r.oid=c.relowner where n.nspname='sky_private' and c.relname in('release_validation_clock','release_validation_witness') and c.relkind='r' and c.relrowsecurity and not c.relforcerowsecurity and r.rolname='postgres')<>2 then raise exception 'Internal validation owner/RLS changed';end if;
 if (select jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'type',k.contype,'definition',pg_get_constraintdef(k.oid),'validated',k.convalidated,'deferrable',k.condeferrable,'deferred',k.condeferred) order by c.relname collate pg_catalog."C",k.conname collate pg_catalog."C") from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='sky_private' and c.relname in('release_validation_clock','release_validation_witness') and k.contype<>'t') is distinct from '[{"table":"release_validation_clock","name":"release_validation_clock_pkey","type":"p","definition":"PRIMARY KEY (singleton)","validated":true,"deferrable":false,"deferred":false},{"table":"release_validation_clock","name":"validation_clock_depth","type":"c","definition":"CHECK ((write_depth >= 0))","validated":true,"deferrable":false,"deferred":false},{"table":"release_validation_clock","name":"validation_clock_epoch","type":"c","definition":"CHECK ((epoch >= 0))","validated":true,"deferrable":false,"deferred":false},{"table":"release_validation_clock","name":"validation_clock_owner","type":"c","definition":"CHECK (((write_depth = 0) = (writer_xid IS NULL)))","validated":true,"deferrable":false,"deferred":false},{"table":"release_validation_clock","name":"validation_clock_singleton","type":"c","definition":"CHECK ((singleton = 1))","validated":true,"deferrable":false,"deferred":false},{"table":"release_validation_witness","name":"release_validation_witness_pkey","type":"p","definition":"PRIMARY KEY (catalog_version)","validated":true,"deferrable":false,"deferred":false},{"table":"release_validation_witness","name":"validation_witness_epoch","type":"c","definition":"CHECK ((epoch >= 0))","validated":true,"deferrable":false,"deferred":false},{"table":"release_validation_witness","name":"validation_witness_release","type":"f","definition":"FOREIGN KEY (catalog_version) REFERENCES sky_private.public_release(catalog_version) ON UPDATE RESTRICT O