aint":false},{"table":"sync_generation","name":"release_validation_write_enter","function":"enter_release_validation_statement","type":30,"enabled":"O","deferrable":false,"deferred":false,"args":0,"argBytes":"","columns":"","condition":null,"oldTransition":null,"newTransition":null,"constraint":false},{"table":"sync_generation","name":"release_validation_write_leave","function":"leave_release_validation_statement","type":28,"enabled":"O","deferrable":false,"deferred":false,"args":0,"argBytes":"","columns":"","condition":null,"oldTransition":null,"newTransition":null,"constraint":false},{"table":"sync_source_state","name":"release_validation_write_enter","function":"enter_release_validation_statement","type":30,"enabled":"O","deferrable":false,"deferred":false,"args":0,"argBytes":"","columns":"","condition":null,"oldTransition":null,"newTransition":null,"constraint":false},{"table":"sync_source_state","name":"release_validation_write_leave","function":"leave_release_validation_statement","type":28,"enabled":"O","deferrable":false,"deferred":false,"args":0,"argBytes":"","columns":"","condition":null,"oldTransition":null,"newTransition":null,"constraint":false},{"table":"tombstone","name":"release_validation_write_enter","function":"enter_release_validation_statement","type":30,"enabled":"O","deferrable":false,"deferred":false,"args":0,"argBytes":"","columns":"","condition":null,"oldTransition":null,"newTransition":null,"constraint":false},{"table":"tombstone","name":"release_validation_write_leave","function":"leave_release_validation_statement","type":28,"enabled":"O","deferrable":false,"deferred":false,"args":0,"argBytes":"","columns":"","condition":null,"oldTransition":null,"newTransition":null,"constraint":false}]'::jsonb then raise exception 'Private write bracket coverage changed';end if;
 if exists(select 1 from pg_policies where schemaname='sky_private' and tablename in('release_validation_clock','release_validation_witness')) then raise exception 'Internal validation policy must remain closed';end if;
 foreach role_name in array array['sky_guide_sync_reader','sky_guide_sync_writer'] loop
  foreach table_name in array array['release_validation_clock','release_validation_witness'] loop
   foreach priv in array array['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER'] loop
    if has_table_privilege(role_name,'sky_private.'||table_name,priv) then raise exception 'Runtime access to internal owner';end if;
   end loop;
   for column_name in select a.attname from pg_attribute a where a.attrelid=('sky_private.'||table_name)::regclass and a.attnum>0 and not a.attisdropped loop
    foreach priv in array array['SELECT','INSERT','UPDATE','REFERENCES'] loop
     if has_column_privilege(role_name,'sky_private.'||table_name,column_name,priv) then raise exception 'Runtime internal column access';end if;
    end loop;
   end loop;
  end loop;
  foreach fn in array array['enter_release_validation_statement()','leave_release_validation_statement()','validate_release_epoch(text)'] loop
   if has_function_privilege(role_name,'sky_private.'||fn,'EXECUTE') is distinct from (role_name='sky_guide_sync_writer' and fn='validate_release_epoch(text)') then raise exception 'Validation helper privilege changed';end if;
  end loop;
 end loop;
 if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a where n.nspname='sky_private' and c.relname in('release_validation_clock','release_validation_witness') and a.grantee<>c.relowner)
 or exists(select 1 from pg_attribute col join pg_class c on c.oid=col.attrelid join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(col.attacl) a where n.nspname='sky_private' and c.relname in('release_validation_clock','release_validation_witness') and a.grantee<>c.relowner) then raise exception 'Nonowner internal ACL';end if;
 if (select coalesce(jsonb_agg(jsonb_build_object('name',p.proname,'grantee',r.rolname,'privilege',a.privilege_type,'grantable',a.is_grantable) order by p.proname collate pg_catalog."C",r.rolname collate pg_catalog."C"),'[]'::jsonb) from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a left join pg_roles r on r.oid=a.grantee where n.nspname='sky_private' and p.proname in('enter_release_validation_statement','leave_release_validation_statement','validate_release_epoch') and a.grantee<>p.proowner) is distinct from '[{"name":"validate_release_epoch","grantee":"sky_guide_sync_writer","privilege":"EXECUTE","grantable":false}]'::jsonb then raise exception 'Validation helper nonowner ACL changed';end if;
end;$validation_catalog$;
do $validation_empty$ declare t text;n bigint;m_versions text[];m_names text[];begin
 if current_user<>'postgres' or current_setting('session_replication_role')<>'origin' then raise exception 'Approved postgres/origin required';end if;
 perform sky_private.lock_sync_commit_control();
 if exists(select 1 from sky_private.sync_generation where singleton<>1 or revision<>0 or current_acceptance_revision is not null or last_promoted_at is not null)
 or exists(select 1 from sky_private.sync_commit_control where singleton<>1 or active_intent_id is not null) then raise exception 'Nonempty generation/control';end if;
 foreach t in array array['acceptance_graph','acceptance_manifest_dataset','acquisition_cost','acquisition_option','acquisition_provenance','acquisition_source_offer','alias','domain_identity','field_provenance','field_provenance_field','graph_alias','graph_call_item','graph_call_media','graph_cosmetic_item','graph_crosswalk','graph_emote_item','graph_emote_media','graph_event_location','graph_identity','graph_identity_provenance','graph_instrument_item','graph_instrument_samples','graph_item_media','graph_item_season','graph_item_spirit','graph_occurrence_event','graph_occurrence_override','graph_occurrence_rule','graph_override_event','graph_override_rule','graph_provenance','graph_rule_event','graph_sample_media','graph_spirit_location','graph_spirit_season','graph_tombstone','identity_provenance','item','item_asset','item_k15','item_rule','item_season','item_source_key','item_spirit','item_translation','payload_provenance','provenance','provenance_order','public_release','release_dataset','release_import_summary','release_item','release_lookup','release_projection','release_projection_file','release_provenance','release_season','release_source','release_source_path','release_source_snapshot','release_spirit','season','season_article','season_item','season_map','season_realm','season_spirit','season_translation','source_crosswalk','source_registry','spirit','spirit_season','spirit_translation','spirit_tree','sync_acceptance','sync_audit','sync_generation','sync_source_state','tombstone','sync_commit_intent','sync_commit_control','sync_commit_applied','sync_commit_receipt','release_validation_clock','release_validation_witness'] loop
  execute format('select count(*) from sky_private.%I',t) into n;
