lse,"columns":["catalog_version","dataset","id","position","owner_revision"]},{"table":"release_lookup","insert":["catalog_version","id","position","owner_revision"],"update":[],"delete":false,"lockOnly":false,"columns":["catalog_version","dataset","id","position","owner_revision"]},{"table":"release_spirit","insert":["catalog_version","id","position","owner_revision"],"update":[],"delete":false,"lockOnly":false,"columns":["catalog_version","dataset","id","position","owner_revision"]},{"table":"release_season","insert":["catalog_version","id","position","owner_revision"],"update":[],"delete":false,"lockOnly":false,"columns":["catalog_version","dataset","id","position","owner_revision"]},{"table":"release_provenance","insert":["catalog_version","id","position"],"update":[],"delete":false,"lockOnly":false,"columns":["catalog_version","dataset","id","position"]},{"table":"acceptance_manifest_dataset","insert":["acceptance_revision","dataset","position"],"update":[],"delete":false,"lockOnly":false,"columns":["acceptance_revision","dataset","position"]},{"table":"source_crosswalk","insert":["source_id","kind","source_key","target_id"],"update":[],"delete":false,"lockOnly":false,"columns":["source_id","kind","source_key","target_id"]},{"table":"alias","insert":["kind","from_id","target_identity_id","target_alias_id"],"update":[],"delete":false,"lockOnly":false,"columns":["kind","from_id","target_identity_id","target_alias_id","to_id"]},{"table":"tombstone","insert":["kind","id","retired_at","replacement_id"],"update":[],"delete":false,"lockOnly":false,"columns":["kind","id","retired_at","replacement_id"]},{"table":"sync_commit_intent","insert":["id","format_version","source_id","expected_revision","state_digest","outcome","attempt_completed_at","next_failures","next_retry_at","next_health","next_success_at","next_valid_until","global_source_id","global_catalog_version","global_content_hash","global_source_hash","global_candidate_hash","global_normalization_version","global_base_revision","global_fetched_at","global_staged_at","global_reviewer_ref","global_reviewed_at","global_promoted_at","global_valid_until"],"update":[],"delete":false,"lockOnly":false,"columns":["id","format_version","source_id","expected_revision","target_revision","state_digest","outcome","attempt_completed_at","next_failures","next_retry_at","next_health","next_success_at","next_valid_until","global_source_id","global_catalog_version","global_content_hash","global_source_hash","global_candidate_hash","global_normalization_version","global_base_revision","global_fetched_at","global_staged_at","global_reviewer_ref","global_reviewed_at","global_promoted_at","global_valid_until"]},{"table":"sync_commit_control","insert":[],"update":["active_intent_id"],"delete":false,"lockOnly":false,"columns":["singleton","active_intent_id"]},{"table":"sync_commit_applied","insert":["intent_id","revision","state_digest"],"update":[],"delete":false,"lockOnly":false,"columns":["intent_id","revision","state_digest"]},{"table":"sync_commit_receipt","insert":["intent_id","resolution"],"update":[],"delete":false,"lockOnly":false,"columns":["intent_id","resolution"]}]'::jsonb) loop
  if has_table_privilege(v_role,'sky_private.'||(v_table->>'table'),'SELECT') is distinct from true then raise exception 'Runtime SELECT changed';end if;
  foreach v_priv in array array['INSERT','UPDATE','TRUNCATE','REFERENCES','TRIGGER'] loop
   if has_table_privilege(v_role,'sky_private.'||(v_table->>'table'),v_priv) is distinct from false then raise exception 'Unexpected blanket table write';end if;
  end loop;
  if has_table_privilege(v_role,'sky_private.'||(v_table->>'table'),'DELETE') is distinct from (v_role='sky_guide_sync_writer' and (v_table->>'delete')::boolean) then raise exception 'Runtime DELETE changed';end if;
