if exists(select 1 from pg_namespace n join pg_roles r on r.oid=n.nspowner where n.nspname='sky_private' and r.rolname in('sky_guide_sync_reader','sky_guide_sync_writer'))
or exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_roles r on r.oid=c.relowner where n.nspname='sky_private' and r.rolname in('sky_guide_sync_reader','sky_guide_sync_writer'))
