do $validation_empty$ declare t text;n bigint;m_versions text[];m_names text[];begin
 if current_user<>'postgres' or current_setting('session_replication_role')<>'origin' then raise exception 'Approved postgres/origin required';end if;
 perform sky_private.lock_sync_commit_control();
 if exists(select 1 from sky_private.sync_generation where singleton<>1 or revision<>0 or current_acceptance_revision is not null or last_promoted_at is not null)
 or exists(select 1 from sky_private.sync_commit_control where singleton<>1 or active_intent_id is not null) then raise exception 'Nonempty generation/control';end if;
 foreach t in array array['acceptance_graph','acceptance_manifest_dataset','acquisition_cost','acquisition_option','acquisition_provenance','acquisition_source_offer','alias','domain_identity','field_provenance','field_provenance_field','graph_alias','graph_call_item','graph_call_media','graph_cosmetic_item','graph_crosswalk','graph_emote_item','graph_emote_media','graph_event_location','graph_identity','graph_identity_provenance','graph_instrument_item','graph_instrument_samples','graph_item_media','graph_item_season','graph_item_spirit','graph_occurrence_event','graph_occurrence_override','graph_occurrence_rule','graph_override_event','graph_override_rule','graph_provenance','graph_rule_event','graph_sample_media','graph_spirit_location','graph_spirit_season','graph_tombstone','identity_provenance','item','item_asset','item_k15','item_rule','item_season','item_source_key','item_spirit','item_translation','payload_provenance','provenance','provenance_order','public_release','release_dataset','release_import_summary','release_item','release_lookup','release_projection','release_projection_file','release_provenance','release_season','release_source','release_source_path','release_source_snapshot','release_spirit','season','season_article','season_item','season_map','season_realm','season_spirit','season_translation','source_crosswalk','source_registry','spirit','spirit_season','spirit_translation','spirit_tree','sync_acceptance','sync_audit','sync_generation','sync_source_state','tombstone','sync_commit_intent','sync_commit_control','sync_commit_applied','sync_commit_receipt'] loop
  execute format('select count(*) from sky_private.%I',t) into n;
  if n<>(case when t in('sync_generation','sync_commit_control') then 1 else 0 end) then raise exception 'Nonempty private owner %',t;end if;
 end loop;
 
 select array_agg(version order by version),array_agg(name order by version) into m_versions,m_names from supabase_migrations.schema_migrations;
 if m_versions[1:15] is distinct from array['20261006170439','20261006171406','20261006171612','20261006173438','20261006174420','20261006180131','20261006181325','20261007014843','20261007020927','20261007022023','20261007023752','20261007132330','20261007132621','20261007160926','20261007161625'] or m_names[1:15] is distinct from array['private_identity_foundation','private_retirement_graph','protect_identity_evidence_truncate','private_catalog_payloads','preserve_instant_fraction_precision','private_release_metadata','immutable_release_projection','private_sync_metadata_cas','private_acceptance_graph','private_acceptance_manifest_order','private_payload_evidence','private_sync_commit_journal','private_journal_runtime_privileges','private_release_metadata_scan','restore_release_metadata_scan'] then raise exception 'Original migration history changed';end if;
 -- The tool may record its own migration before or after executing supplied SQL.
 if cardinality(m_versions) not between 16 and 17
 or (cardinality(m_versions)>=16 and m_names[16] is distinct from 'private_release_validation_brackets')
 or (cardinality(m_versions)=17 and m_names[17] is distinct from 'restore_private_release_validation_brackets')
 then raise exception 'Unexpected extra migration history';end if;
end;$validation_empty$;
